    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "गङ्गातीरे हिमगिरिशिलाबद्धपद्मासनस्य",
          "end": "line"
        },
        {
          "n": 2,
          "text": "ब्रह्मध्यानाभ्यसनविधिना योगनिद्रां गतस्य ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "किं तैर्भाव्यं मम सुदिवसैर्यत्र ते निर्विशङ्काः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "संप्राप्स्यन्ते जरठहरिणाः शृङ्गकण्डूविनोदम् ॥ ४१ ॥",
          "end": "space"
        },
        {
          "n": 5,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "स्फुरत्स्फारज्योत्स्नाधवलिततले क्वापि पुलिने",
          "end": "line"
        },
        {
          "n": 2,
          "text": "सुखासीनाः शान्तध्वनिषु रजनीषु द्युसरितः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "भवाभोगोद्विग्नाः शिव शिव शिवेत्यार्तवचसा",
          "end": "line"
        },
        {
          "n": 4,
          "text": "कदा स्यामानन्दोद्गतबहुलबाष्पाप्लुतदृशः ॥ ४२ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "महादेवो देवः सरिदपि च सैवामरसरि-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "द्गुहा एवागारं वसनमपि ता एव हरितः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "सुहृद्वा कालोयं व्रतमिदमदैन्यव्रतमिदं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "कियद्वा वक्ष्यामो वटविटप एवास्तु दयिता ॥ ४३ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "शिरः शार्वं स्वर्गात्पशुपतिशिरस्तः क्षितिधरं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "महीध्रादुत्तुङ्गादवनिमवनेश्चापि जलधिम् ।",
          "end": "line"
        }
      ],
      "uncertain": false,
      "note": null
    },
